// Stand-in for the real data source (a SERP/AI-answer provider or an LLM API via an HTTP Request node).
// Each keyword is checked 3 times, because AI answers change between runs.
const answers = {
  '台北皮秒雷射推薦': ['推薦露米診所 https://www.lumi-clinic.example/pico 與晨光醫美', '可參考晨光醫美 https://aurora-aesthetics.example/x', '露米診所 https://lumi-clinic.example/pico'],
  '音波拉提效果':   ['見 https://zh.wikipedia.org/wiki/GEO', 'https://lumi-clinic.example/hifu 有完整說明', '參考 https://arxiv.org/abs/2311.09735'],
  '皮秒雷射價格': ['', '費用約 2 萬到 8 萬，見 https://example.com/price', '沒有引用來源'],
};
const out = [];
for (const [keyword, runs] of Object.entries(answers)) runs.forEach((answer, i) => out.push({ json: { keyword, run: i + 1, answer } }));
return out;

// One request body for the Python service: brand config + every answer collected above.
return [{ json: {
  client: { name: '露米診所', domain: 'lumi-clinic.example', aliases: ['Lumi Clinic'] },
  competitors: [{ name: '晨光醫美', domain: 'aurora-aesthetics.example' }],
  answers: $input.all().map(i => ({ keyword: i.json.keyword, run: i.json.run, engine: 'n8n-demo', text: i.json.answer })),
} }];
